<section id="terminy"><div class="admin-section-title"><p class="eyebrow">VÁŠ ČAS NA FOCENÍ</p><h2>Volné termíny</h2><p>Zvolte začátek a balíček. Konec dopočítáme podle jeho délky. Bez balíčku má termín 2 hodiny. Více termínů vytvoříme za sebou; pro další den přidejte další sérii.</p></div>
<form class="slot-create panel" method="post" action="/?admin=1"><?= csrf_field() ?><input type="hidden" name="action" value="save_slot"><div class="form-row"><label>Začátek prvního termínu<input name="starts_at" type="datetime-local" required min="<?= date('Y-m-d\TH:i') ?>"></label><label>Balíček<select name="package_id"><option value="0">Bez balíčku · 120 min</option><?php foreach ($allPackages as $package): if (!$package['is_active'] || $package['is_individual']) continue; ?><option value="<?= (int)$package['id'] ?>"><?= e(package_label($package)) ?></option><?php endforeach; ?></select></label></div><div class="form-row"><label>Počet navazujících termínů<input type="number" name="count" min="1" max="20" value="1" required></label><label>Místo focení<input name="location" maxlength="160" placeholder="Např. Poděbrady · park"></label></div><button class="button">Vypsat termíny +</button></form>
<?php if (!$slots): ?><p class="empty">Zatím nemáte vypsané termíny. Přidejte první sérii.</p><?php endif; ?><div class="slot-list"><?php foreach ($slots as $s): $slotPackage = null; foreach ($allPackages as $p) if ((int)$p['id']===(int)$s['package_id']) $slotPackage=$p; ?><article class="slot-card"><div><span class="badge"><?= e($slotPackage['name'] ?? 'Bez balíčku') ?></span><h3><?= e(slot_label($s)) ?></h3><p><?= $s['booking_id'] ? e(STATES[$s['booking_status']]) . ' · ' . e($s['booking_name']) : ($s['starts_at'] <= date('Y-m-d H:i:s') ? 'Proběhlý termín' : ($s['is_open'] ? 'Volný' : 'Uzavřený')) ?></p></div><?php if (!$s['booking_id']): ?><div class="slot-tools"><form method="post" action="/?admin=1"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_slot"><input type="hidden" name="slot_id" value="<?= (int)$s['id'] ?>"><button class="secondary-button"><?= $s['is_open'] ? 'Uzavřít' : 'Znovu otevřít' ?></button></form><?php if ($s['starts_at'] > date('Y-m-d H:i:s')): ?><details><summary>Upravit</summary><form method="post" action="/?admin=1"><?= csrf_field() ?><input type="hidden" name="action" value="save_slot"><input type="hidden" name="slot_id" value="<?= (int)$s['id'] ?>"><label>Začátek<input type="datetime-local" name="starts_at" required value="<?= e(date('Y-m-d\TH:i',strtotime($s['starts_at']))) ?>"></label><label>Balíček<select name="package_id"><option value="0">Bez balíčku · 120 min</option><?php foreach ($allPackages as $p): if ($p['is_individual'] || !$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>" <?= (int)$p['id']===(int)$s['package_id'] ? 'selected' : '' ?>><?= e(package_label($p)) ?></option><?php endforeach; ?></select></label><label>Místo<input name="location" maxlength="160" value="<?= e($s['location']) ?>"></label><button class="secondary-button">Uložit termín</button></form></details><?php endif; ?></div><?php endif; ?></article><?php endforeach; ?></div></section>
